test "cli_date: empty argv yields the dflt defaults" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const gpa = arena_state.allocator();
    const argv = [_][]const u8{ "fx-date" };
    const o = try parsePosix(&argv, gpa);
    try std.testing.expectEqualStrings("%a %b %e %H:%M:%S %Z %Y", o.format);
    try std.testing.expectEqual(false, o.utc);
}

test "cli_date: -u binds utc" {
