    defer arena_state.deinit();
    const gpa = arena_state.allocator();
    const argv = [_][]const u8{ "fx-date", "-u" };
    const o = try parsePosix(&argv, gpa);
    try std.testing.expect(o.utc);
}

test "cli_date: cluster with unknown letter rejected" {
